package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.std.TypeDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

/**
 * Unit tests for StringArrayDeserializer#deserializeWithType
 */
public class StringArrayDeserializer_deserializeWithType_TriageGen2Test {

    private StringArrayDeserializer deserializer;
    private JsonParser mockJsonParser;
    private DeserializationContext mockDeserializationContext;
    private TypeDeserializer mockTypeDeserializer;

    @Before
    public void setUp() {
        deserializer = new StringArrayDeserializer();
        mockJsonParser = Mockito.mock(JsonParser.class);
        mockDeserializationContext = Mockito.mock(DeserializationContext.class);
        mockTypeDeserializer = Mockito.mock(TypeDeserializer.class);
    }

    @Test
    public void testDeserializeWithType_Success() throws IOException {
        // Arrange
        String[] expectedResult = {"apple", "banana", "cherry"};
        when(mockTypeDeserializer.deserializeTypedFromArray(mockJsonParser, mockDeserializationContext))
                .thenReturn(expectedResult);

        // Act
        Object actualResult = deserializer.deserializeWithType(mockJsonParser, mockDeserializationContext, mockTypeDeserializer);

        // Assert
        assertEquals(expectedResult, actualResult);
        verify(mockTypeDeserializer).deserializeTypedFromArray(mockJsonParser, mockDeserializationContext);
    }

    @Test
    public void testDeserializeWithType_ReturnsNull() throws IOException {
        // Arrange
        when(mockTypeDeserializer.deserializeTypedFromArray(mockJsonParser, mockDeserializationContext))
                .thenReturn(null);

        // Act
        Object actualResult = deserializer.deserializeWithType(mockJsonParser, mockDeserializationContext, mockTypeDeserializer);

        // Assert
        assertEquals(null, actualResult);
        verify(mockTypeDeserializer).deserializeTypedFromArray(mockJsonParser, mockDeserializationContext);
    }

    @Test(expected = IOException.class)
    public void testDeserializeWithType_ThrowsIOException() throws IOException {
        // Arrange
        when(mockTypeDeserializer.deserializeTypedFromArray(mockJsonParser, mockDeserializationContext))
                .thenThrow(new IOException("Simulated IO Exception"));

        // Act
        deserializer.deserializeWithType(mockJsonParser, mockDeserializationContext, mockTypeDeserializer);

        // Assert handled by expected exception
    }

    @Test
    public void testDeserializeWithType_ReturnsDifferentObjectType() throws IOException {
        // Arrange
        // Although the class is StringArrayDeserializer, the method returns Object, 
        // so we test if it correctly passes through whatever the typeDeserializer returns.
        Integer expectedResult = 123;
        when(mockTypeDeserializer.deserializeTypedFromArray(mockJsonParser, mockDeserializationContext))
                .thenReturn(expectedResult);

        // Act
        Object actualResult = deserializer.deserializeWithType(mockJsonParser, mockDeserializationContext, mockTypeDeserializer);

        // Assert
        assertEquals(expectedResult, actualResult);
        verify(mockTypeDeserializer).deserializeTypedFromArray(mockJsonParser, mockDeserializationContext);
    }
}
